do $python_seed$
declare
 v_owner uuid := 'a76b3f06-88fa-4a1a-8b2e-7ea55ef6ba15';
 v_path uuid := '5f2daeac-e73f-5d25-adb5-e0f16ca78335';
 v_plan jsonb := '[{"id":"6a4b88cd-ce49-5943-8d35-8ccf290dd1df","title":"Week 1 — Python First Steps","goal":"Set up an environment and write small programs using input, output, variables and strings.","days":[{"id":"f56abd22-8033-5477-b5c1-e893c7bf5177","dayLabel":"Lesson 1","title":"Your First Python Program","hours":"1.00","contentMarkdown":"## Learning objective\nRun Python and explain what an interpreter does.\n\n## Understand\nPython executes statements in sequence. Use `print()` to display text, distinguish source code from output, and understand how syntax errors differ from runtime errors. Choose a browser-based environment or a local Python installation.\n\n## Watch\n- **Watch:** [Corey Schafer — Python Beginner Tutorials (YouTube)](https://www.youtube.com/playlist?list=PL-osiE80TeTskrapNbzXhwoFUiLCjGgY7)\n\n## Read\n- **Read:** [Harvard CS50P — Functions and Variables](https://cs50.harvard.edu/python/weeks/0/)\n- **Read · optional:** [Kaggle — Intro to Programming](https://www.kaggle.com/learn/intro-to-programming)\n\n## Practice activity\nRun Hello World, change the greeting, and deliberately correct a syntax error.\n\n## Expected outcome\nCan run and edit a Python program.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"dd32baa7-7453-5110-b80a-812bf6e1f197","title":"Complete lesson 1: Your First Python Program","url":"https://cs50.harvard.edu/python/weeks/0/","tag":"hands"}]},{"id":"3e0b5285-8863-56b2-b98f-9a4f05204792","dayLabel":"Lesson 2","title":"Variables, Numbers and Operators","hours":"1.08","contentMarkdown":"## Learning objective\nStore values and perform arithmetic safely.\n\n## Understand\nUse assignment to name values, and distinguish integers from floating-point numbers. Practice `+`, `-`, `*`, `/`, `//`, `%` and `**`; explain how parentheses affect evaluation. Use meaningful names and avoid overwriting built-in names.\n\n## Read\n- **Read:** [Kaggle — Intro to Programming](https://www.kaggle.com/learn/intro-to-programming)\n- **Read:** [Automate the Boring Stuff — Chapter 1](https://automatetheboringstuff.com/3e/chapter1.html)\n- **Read · optional:** [Harvard CS50P — Functions and Variables](https://cs50.harvard.edu/python/weeks/0/)\n\n## Practice activity\nCalculate a shopping bill with tax, discounts, and a per-person split.\n\n## Expected outcome\nCan compute numeric results with variables.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"30ef927b-de27-5176-ba72-ab43eb6a199c","title":"Complete lesson 2: Variables, Numbers and Operators","url":"https://www.kaggle.com/learn/intro-to-programming","tag":"hands"}]},{"id":"f254a7ec-2f46-5d0c-97cd-65fd9219b169","dayLabel":"Lesson 3","title":"Strings and Formatting","hours":"1.17","contentMarkdown":"## Learning objective\nCreate and transform human-readable text.\n\n## Understand\nStrings represent text; practice quoting, concatenation, length, indexing, and simple methods such as `strip()` and `lower()`. Use f-strings to embed values and format numbers, including two-decimal currency output.\n\n## Watch\n- **Watch:** [Corey Schafer — Python Beginner Tutorials (YouTube)](https://www.youtube.com/playlist?list=PL-osiE80TeTskrapNbzXhwoFUiLCjGgY7)\n\n## Read\n- **Read:** [Harvard CS50P — Functions and Variables](https://cs50.harvard.edu/python/weeks/0/)\n- **Read · optional:** [Official Python Tutorial](https://docs.python.org/3/tutorial/index.html)\n\n## Practice activity\nBuild a personalized welcome message and format an invoice summary.\n\n## Expected outcome\nCan manipulate strings and format output.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"fbd10a4d-26b3-5d44-9611-4a6389ceeff0","title":"Complete lesson 3: Strings and Formatting","url":"https://cs50.harvard.edu/python/weeks/0/","tag":"hands"}]},{"id":"947acd46-2be2-5a78-9afe-e803ab3e9d43","dayLabel":"Lesson 4","title":"Input, Types and Conversion","hours":"1.17","contentMarkdown":"## Learning objective\nAccept and validate basic user input.\n\n## Understand\n`input()` returns text even when the user types digits. Convert with `int()` or `float()` and distinguish conversion errors from valid values. Explain why programs should not assume user input is already clean.\n\n## Read\n- **Read:** [Harvard CS50P — Functions and Variables](https://cs50.harvard.edu/python/weeks/0/)\n- **Read:** [Kaggle — Intro to Programming](https://www.kaggle.com/learn/intro-to-programming)\n\n## Practice\n- **Practice · optional:** [Python Tutor — Visualize Execution](https://pythontutor.com/)\n\n## Practice activity\nAsk for name, age, and monthly savings; show an annual estimate.\n\n## Expected outcome\nCan build a simple interactive script.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"0b5e4996-e7a7-5f0a-a862-654c9c355301","title":"Complete lesson 4: Input, Types and Conversion","url":"https://cs50.harvard.edu/python/weeks/0/","tag":"hands"}]},{"id":"32e3b09e-6922-5772-840f-f1525b82fb62","dayLabel":"Lesson 5","title":"Project: Expense & Tip Calculator","hours":"1.58","contentMarkdown":"## Learning objective\nCombine variables, input, formatting and arithmetic.\n\n## Understand\nBuild a command-line calculator that accepts a bill amount, tip percentage, and number of people. Calculate total and per-person share, print readable results, and include two example runs. Error handling can be added in Week 4.\n\n## Read\n- **Read:** [Automate the Boring Stuff — Chapter 1](https://automatetheboringstuff.com/3e/chapter1.html)\n- **Read:** [Harvard CS50P — Functions and Variables](https://cs50.harvard.edu/python/weeks/0/)\n\n## Practice\n- **Practice · optional:** [Exercism — Python Track](https://exercism.org/tracks/python)\n\n## Practice activity\nCreate the script, try three different values, and record what you would improve.\n\n## Expected outcome\nCompletes a small practical program.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"ca7fb62c-5f8c-581f-b346-a7fae8c4f220","title":"Complete lesson 5: Project: Expense & Tip Calculator","url":"https://automatetheboringstuff.com/3e/chapter1.html","tag":"hands"}]}]},{"id":"f3499418-728e-5c65-a84b-4edeb073f760","title":"Week 2 — Control Flow and Loops","goal":"Write programs that make decisions and repeat tasks.","days":[{"id":"4c799e2e-fe6a-5435-9e58-4784554b9100","dayLabel":"Lesson 6","title":"Booleans and Comparisons","hours":"1.08","contentMarkdown":"## Learning objective\nUse Boolean expressions to compare values.\n\n## Understand\nA Boolean is `True` or `False`. Practice comparison operators and `and`, `or`, and `not`; show how combining conditions controls program behavior. Explain that `=` assigns while `==` compares.\n\n## Read\n- **Read:** [Harvard CS50P — Conditionals](https://cs50.harvard.edu/python/weeks/1/)\n- **Read:** [Kaggle Learn — Python](https://www.kaggle.com/learn/python)\n\n## Practice\n- **Practice · optional:** [Python Tutor — Visualize Execution](https://pythontutor.com/)\n\n## Practice activity\nClassify a temperature as cold, warm or hot using expressions.\n\n## Expected outcome\nCan evaluate simple conditions.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"40f4eae0-cece-5817-9c70-d7cd397c2924","title":"Complete lesson 6: Booleans and Comparisons","url":"https://cs50.harvard.edu/python/weeks/1/","tag":"hands"}]},{"id":"1455d79e-c6de-55a2-ad5d-3c48db31db44","dayLabel":"Lesson 7","title":"If, Elif, Else","hours":"1.25","contentMarkdown":"## Learning objective\nWrite readable conditional branches.\n\n## Understand\nUse indentation to group branches. Arrange specific conditions before general ones and use `elif` to avoid conflicting decisions. Build clear messages for valid and invalid inputs.\n\n## Read\n- **Read:** [Harvard CS50P — Conditionals](https://cs50.harvard.edu/python/weeks/1/)\n- **Read:** [Automate the Boring Stuff — Chapter 2](https://automatetheboringstuff.com/3e/chapter2.html)\n- **Read · optional:** [University of Helsinki — Python Programming MOOC 2026](https://programming-26.mooc.fi/)\n\n## Practice activity\nCreate a ticket-pricing or grading decision program.\n\n## Expected outcome\nCan implement multi-branch logic.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"ef45a0bb-e55b-5d74-bcf8-65f02fb79184","title":"Complete lesson 7: If, Elif, Else","url":"https://cs50.harvard.edu/python/weeks/1/","tag":"hands"}]},{"id":"9ee37915-5cb1-5475-970c-f3e711c39b42","dayLabel":"Lesson 8","title":"For Loops and Range","hours":"1.17","contentMarkdown":"## Learning objective\nIterate over sequences and known counts.\n\n## Understand\n`for` iterates through items; `range()` generates a numeric sequence. Introduce accumulators and counters, and demonstrate why loop variable naming matters. Use Python Tutor to observe each iteration.\n\n## Read\n- **Read:** [Harvard CS50P — Loops](https://cs50.harvard.edu/python/weeks/2/)\n- **Read · optional:** [Kaggle Learn — Python](https://www.kaggle.com/learn/python)\n\n## Practice\n- **Practice:** [Python Tutor — Visualize Execution](https://pythontutor.com/)\n\n## Practice activity\nPrint a multiplication table and sum expenses from a list.\n\n## Expected outcome\nCan automate repeated calculations.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"acbbbbce-82b3-5e70-a30f-b9e5c77f4cdb","title":"Complete lesson 8: For Loops and Range","url":"https://cs50.harvard.edu/python/weeks/2/","tag":"hands"}]},{"id":"55955ae8-24f9-5fed-8594-20aaf0bb9f91","dayLabel":"Lesson 9","title":"While Loops and Loop Control","hours":"1.25","contentMarkdown":"## Learning objective\nRepeat until a condition changes.\n\n## Understand\nUse `while` for repetition driven by user choices or state. Discuss termination conditions and infinite loops. Use `break` and `continue` sparingly and explain when each is appropriate.\n\n## Read\n- **Read:** [Harvard CS50P — Loops](https://cs50.harvard.edu/python/weeks/2/)\n- **Read:** [Automate the Boring Stuff — Chapter 3](https://automatetheboringstuff.com/3e/chapter3.html)\n- **Read · optional:** [University of Helsinki — Python Programming MOOC 2026](https://programming-26.mooc.fi/)\n\n## Practice activity\nCreate a menu that repeats until the user selects Exit.\n\n## Expected outcome\nCan design a terminating interactive loop.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"7387e71a-3a5f-5225-ab87-9865c005bc41","title":"Complete lesson 9: While Loops and Loop Control","url":"https://cs50.harvard.edu/python/weeks/2/","tag":"hands"}]},{"id":"13d824bf-327a-57fc-abf7-dc58a73a916e","dayLabel":"Lesson 10","title":"Project: Number Guessing Game","hours":"1.50","contentMarkdown":"## Learning objective\nCombine loops, branching and user input.\n\n## Understand\nGenerate a secret number, repeatedly request a guess, and respond with too high or too low. Count attempts and end when correct. Optionally limit guesses. Do not assume all user input is valid; note validation improvements for Week 4.\n\n## Read\n- **Read:** [Harvard CS50P — Loops](https://cs50.harvard.edu/python/weeks/2/)\n- **Read:** [Harvard CS50P — Libraries](https://cs50.harvard.edu/python/weeks/4/)\n\n## Practice\n- **Practice · optional:** [Exercism — Python Track](https://exercism.org/tracks/python)\n\n## Practice activity\nImplement the game, test winning and losing paths, and write a brief explanation of its control flow.\n\n## Expected outcome\nCompletes an interactive guessing game.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"ddffa38b-4cef-58c5-846c-bfc9cdaf8af7","title":"Complete lesson 10: Project: Number Guessing Game","url":"https://cs50.harvard.edu/python/weeks/2/","tag":"hands"}]}]},{"id":"e1576586-3fe8-57cf-9a8c-6882dbbd6fd1","title":"Week 3 — Working with Collections","goal":"Use lists, tuples, sets, dictionaries and string operations to organize data.","days":[{"id":"d263bef6-8d7e-5a25-8598-2f4350d3bb97","dayLabel":"Lesson 11","title":"Lists and Indexing","hours":"1.17","contentMarkdown":"## Learning objective\nCreate, update and traverse lists.\n\n## Understand\nLists are ordered and mutable. Learn indexing, negative indexes, slicing, `append()`, `remove()`, and sorting. Contrast accessing a value with modifying a list.\n\n## Watch\n- **Watch · optional:** [Corey Schafer — Python Beginner Tutorials (YouTube)](https://www.youtube.com/playlist?list=PL-osiE80TeTskrapNbzXhwoFUiLCjGgY7)\n\n## Read\n- **Read:** [Kaggle Learn — Python](https://www.kaggle.com/learn/python)\n- **Read:** [Official Python Tutorial](https://docs.python.org/3/tutorial/index.html)\n\n## Practice activity\nMaintain a list of five study topics and mark a topic as completed.\n\n## Expected outcome\nCan manage a changing collection.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"32e1fb82-dc33-57af-a586-cb195d281995","title":"Complete lesson 11: Lists and Indexing","url":"https://www.kaggle.com/learn/python","tag":"hands"}]},{"id":"35861345-d214-502c-8446-80b80f7ddf39","dayLabel":"Lesson 12","title":"Tuples and Sets","hours":"1.17","contentMarkdown":"## Learning objective\nChoose suitable collection types.\n\n## Understand\nTuples are ordered and typically used for fixed groupings; sets hold unique elements. Practice membership tests and basic set operations. Compare trade-offs against lists.\n\n## Watch\n- **Watch:** [Corey Schafer — Python Beginner Tutorials (YouTube)](https://www.youtube.com/playlist?list=PL-osiE80TeTskrapNbzXhwoFUiLCjGgY7)\n\n## Read\n- **Read:** [Official Python Tutorial](https://docs.python.org/3/tutorial/index.html)\n- **Read · optional:** [University of Helsinki — Python Programming MOOC 2026](https://programming-26.mooc.fi/)\n\n## Practice activity\nDeduplicate a list of course tags and represent fixed coordinates.\n\n## Expected outcome\nCan choose between list, tuple and set.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"e110cd6b-8b10-5b47-8cfe-cb1c6f583937","title":"Complete lesson 12: Tuples and Sets","url":"https://docs.python.org/3/tutorial/index.html","tag":"hands"}]},{"id":"a82c09f1-6c0d-5374-b2a6-f262a82866de","dayLabel":"Lesson 13","title":"Dictionaries and Nested Data","hours":"1.25","contentMarkdown":"## Learning objective\nModel key-value records.\n\n## Understand\nDictionaries map keys to values. Use `get()`, key membership, iteration and nested dictionaries. Represent a contact with name, phone and email; distinguish missing keys from empty values.\n\n## Read\n- **Read:** [Kaggle Learn — Python](https://www.kaggle.com/learn/python)\n- **Read:** [Automate the Boring Stuff — Chapter 7](https://automatetheboringstuff.com/3e/chapter7.html)\n- **Read · optional:** [Official Python Tutorial](https://docs.python.org/3/tutorial/index.html)\n\n## Practice activity\nCreate a contact record and update one field safely.\n\n## Expected outcome\nCan model structured records.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"a1fcce7e-9850-558e-9432-01b943dd6c9c","title":"Complete lesson 13: Dictionaries and Nested Data","url":"https://www.kaggle.com/learn/python","tag":"hands"}]},{"id":"5422223a-bcb4-5020-a608-d961abd196ee","dayLabel":"Lesson 14","title":"String Processing and Comprehensions","hours":"1.25","contentMarkdown":"## Learning objective\nTransform collections concisely without obscuring meaning.\n\n## Understand\nPractice `split()`, `join()`, `replace()` and membership in strings. Introduce simple list comprehensions after equivalent loops, and avoid complex nested one-liners.\n\n## Read\n- **Read:** [Kaggle Learn — Python](https://www.kaggle.com/learn/python)\n- **Read:** [Automate the Boring Stuff — Chapter 8](https://automatetheboringstuff.com/3e/chapter8.html)\n\n## Practice\n- **Practice · optional:** [Python Tutor — Visualize Execution](https://pythontutor.com/)\n\n## Practice activity\nNormalize a list of messy names and extract names above a minimum length.\n\n## Expected outcome\nCan clean simple text collections.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"c903722c-9be4-5b5b-9cc2-149795323ee3","title":"Complete lesson 14: String Processing and Comprehensions","url":"https://www.kaggle.com/learn/python","tag":"hands"}]},{"id":"eb845d54-33a7-5814-8a7f-0cbef5214445","dayLabel":"Lesson 15","title":"Project: Contact Book","hours":"1.67","contentMarkdown":"## Learning objective\nCombine dictionaries, lists, search and menus.\n\n## Understand\nStore contacts as dictionaries in a list or dictionary keyed by name. Support add, list, search and update operations in memory. Focus on clear interaction and predictable data shape; persistence comes next week.\n\n## Read\n- **Read:** [Kaggle Learn — Python](https://www.kaggle.com/learn/python)\n- **Read · optional:** [University of Helsinki — Python Programming MOOC 2026](https://programming-26.mooc.fi/)\n\n## Practice\n- **Practice:** [Exercism — Python Track](https://exercism.org/tracks/python)\n\n## Practice activity\nCreate at least five contacts, search by name, and handle an unknown contact.\n\n## Expected outcome\nBuilds a useful in-memory contact manager.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"3c3965d5-3273-5de2-b4ec-d2a431632a17","title":"Complete lesson 15: Project: Contact Book","url":"https://www.kaggle.com/learn/python","tag":"hands"}]}]},{"id":"3fa1c524-3370-573e-8c8f-bb6e17ba5d51","title":"Week 4 — Functions and Reliable Programs","goal":"Write reusable functions, use modules and debug failures.","days":[{"id":"f0b293bc-2917-542b-86dc-cdc7880db70d","dayLabel":"Lesson 16","title":"Functions and Return Values","hours":"1.17","contentMarkdown":"## Learning objective\nBreak work into small reusable units.\n\n## Understand\nUse `def`, parameters and `return`. Explain the difference between printing a result and returning a value to a caller. Practice writing functions that do one job.\n\n## Read\n- **Read:** [Harvard CS50P — Functions and Variables](https://cs50.harvard.edu/python/weeks/0/)\n- **Read:** [Automate the Boring Stuff — Chapter 4](https://automatetheboringstuff.com/3e/chapter4.html)\n- **Read · optional:** [Kaggle Learn — Python](https://www.kaggle.com/learn/python)\n\n## Practice activity\nRefactor a repeated price calculation into a reusable function.\n\n## Expected outcome\nCan define and call functions.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"d9edbd49-e56e-5b73-9542-4b89caa0eb0d","title":"Complete lesson 16: Functions and Return Values","url":"https://cs50.harvard.edu/python/weeks/0/","tag":"hands"}]},{"id":"410e2343-a163-52e0-9f11-a9439097bfc8","dayLabel":"Lesson 17","title":"Arguments, Scope and Docstrings","hours":"1.25","contentMarkdown":"## Learning objective\nDesign understandable function interfaces.\n\n## Understand\nPractice positional, keyword and default arguments. Discuss local variables and why global state makes behavior harder to reason about. Write concise docstrings and use descriptive function names.\n\n## Watch\n- **Watch · optional:** [Corey Schafer — Python Beginner Tutorials (YouTube)](https://www.youtube.com/playlist?list=PL-osiE80TeTskrapNbzXhwoFUiLCjGgY7)\n\n## Read\n- **Read:** [Official Python Tutorial](https://docs.python.org/3/tutorial/index.html)\n- **Read:** [Harvard CS50P — Functions and Variables](https://cs50.harvard.edu/python/weeks/0/)\n\n## Practice activity\nCreate `calculate_total(amount, tax_rate=0)` and document it.\n\n## Expected outcome\nCan write simple maintainable functions.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"108c430f-0d0a-5c6d-b925-903e17c3774d","title":"Complete lesson 17: Arguments, Scope and Docstrings","url":"https://docs.python.org/3/tutorial/index.html","tag":"hands"}]},{"id":"d5a98b38-6a5b-5c60-b16d-a41b9b112d16","dayLabel":"Lesson 18","title":"Modules and Standard Library","hours":"1.17","contentMarkdown":"## Learning objective\nReuse code from modules.\n\n## Understand\nUse `import`, `from ... import`, and selected standard-library modules such as `math`, `random` and `datetime`. Understand that third-party packages differ from the standard library.\n\n## Read\n- **Read:** [Harvard CS50P — Libraries](https://cs50.harvard.edu/python/weeks/4/)\n- **Read:** [Official Python Tutorial](https://docs.python.org/3/tutorial/index.html)\n- **Read · optional:** [Kaggle Learn — Python](https://www.kaggle.com/learn/python)\n\n## Practice activity\nSplit a utility into two Python files and import one function.\n\n## Expected outcome\nCan organize code across files.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"b2e770f8-355f-5419-89c7-6bfa2f81cdbb","title":"Complete lesson 18: Modules and Standard Library","url":"https://cs50.harvard.edu/python/weeks/4/","tag":"hands"}]},{"id":"191e6548-77d6-5055-ac60-8571e21895bd","dayLabel":"Lesson 19","title":"Exceptions and Debugging","hours":"1.33","contentMarkdown":"## Learning objective\nHandle predictable errors and inspect execution.\n\n## Understand\nUse `try`/`except` for known failures such as invalid number conversion. Avoid catching every exception silently. Read tracebacks, reproduce bugs with small inputs, and step through loops and function calls in Python Tutor.\n\n## Read\n- **Read:** [Harvard CS50P — Exceptions](https://cs50.harvard.edu/python/weeks/3/)\n- **Read · optional:** [Automate the Boring Stuff — Chapter 5](https://automatetheboringstuff.com/3e/chapter5.html)\n\n## Practice\n- **Practice:** [Python Tutor — Visualize Execution](https://pythontutor.com/)\n\n## Practice activity\nMake Week 1 calculator handle blank and nonnumeric inputs; trace a failing case.\n\n## Expected outcome\nCan diagnose and recover from common errors.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"b53afe05-aa38-58db-84b6-ff3135aef5e9","title":"Complete lesson 19: Exceptions and Debugging","url":"https://cs50.harvard.edu/python/weeks/3/","tag":"hands"}]},{"id":"5dbf6b2e-f2c6-519d-b9d8-1be4a6d312ff","dayLabel":"Lesson 20","title":"Project: Modular Calculator","hours":"1.58","contentMarkdown":"## Learning objective\nCombine functions, imports and error handling.\n\n## Understand\nBuild a menu-driven calculator with separate arithmetic functions, validated input and meaningful errors. Include a `main()` function and protect script execution with `if __name__ == \"__main__\"`.\n\n## Read\n- **Read:** [Harvard CS50P — Exceptions](https://cs50.harvard.edu/python/weeks/3/)\n- **Read:** [Harvard CS50P — Libraries](https://cs50.harvard.edu/python/weeks/4/)\n\n## Practice\n- **Practice · optional:** [Exercism — Python Track](https://exercism.org/tracks/python)\n\n## Practice activity\nRun positive, negative, decimal, division-by-zero and invalid-input scenarios.\n\n## Expected outcome\nProduces a reusable and resilient command-line tool.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"8d316b77-8cb6-5e2e-8824-25d65dc8e087","title":"Complete lesson 20: Project: Modular Calculator","url":"https://cs50.harvard.edu/python/weeks/3/","tag":"hands"}]}]},{"id":"801a9251-13ec-5c0c-b4cb-da632e7d9397","title":"Week 5 — Files, CSV and JSON","goal":"Save, load and transform real data using the standard library.","days":[{"id":"1eadd2f5-f320-5fee-af1b-b6d740d24fc8","dayLabel":"Lesson 21","title":"Reading and Writing Text","hours":"1.17","contentMarkdown":"## Learning objective\nPersist information across program runs.\n\n## Understand\nUse `with open(...)` for safe file handling, specify encoding, and distinguish reading from overwriting and appending. Explain why file paths and permissions can fail.\n\n## Read\n- **Read:** [Harvard CS50P — File I/O](https://cs50.harvard.edu/python/weeks/6/)\n- **Read:** [Automate the Boring Stuff — Chapter 10](https://automatetheboringstuff.com/3e/chapter10.html)\n- **Read · optional:** [Official Python Tutorial](https://docs.python.org/3/tutorial/index.html)\n\n## Practice activity\nWrite a study journal to a text file and read it back.\n\n## Expected outcome\nCan save and load text safely.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"688202ea-8066-55f4-b140-16f3a2bb776c","title":"Complete lesson 21: Reading and Writing Text","url":"https://cs50.harvard.edu/python/weeks/6/","tag":"hands"}]},{"id":"bc7b8eac-5436-5d8f-95bf-28003b8d95ed","dayLabel":"Lesson 22","title":"Paths and File Safety","hours":"1.17","contentMarkdown":"## Learning objective\nWork with directories and paths portably.\n\n## Understand\nUse `pathlib.Path` to construct paths and inspect files. Distinguish relative and absolute paths; avoid hard-coded machine-specific paths. Introduce backups and previewing destructive file operations.\n\n## Read\n- **Read:** [Official Python — pathlib module](https://docs.python.org/3/library/pathlib.html)\n- **Read:** [Automate the Boring Stuff — Chapter 11](https://automatetheboringstuff.com/3e/chapter11.html)\n- **Read · optional:** [Official Python Tutorial](https://docs.python.org/3/tutorial/index.html)\n\n## Practice activity\nCreate an output folder and list files without modifying them.\n\n## Expected outcome\nCan handle file locations safely.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"92a37996-f499-52b2-bf5a-b46b4466501e","title":"Complete lesson 22: Paths and File Safety","url":"https://docs.python.org/3/library/pathlib.html","tag":"hands"}]},{"id":"bbbfaa58-4235-5298-b6b2-2d9bd8360d08","dayLabel":"Lesson 23","title":"CSV Records","hours":"1.25","contentMarkdown":"## Learning objective\nRead and write tabular information.\n\n## Understand\nCSV stores rows of values. Use `csv.DictReader` and `csv.DictWriter` to keep column names explicit. Explain headers, missing values, numeric conversion and why commas inside quoted values require a CSV parser.\n\n## Read\n- **Read:** [Official Python — csv module](https://docs.python.org/3/library/csv.html)\n- **Read:** [Automate the Boring Stuff — Chapter 18](https://automatetheboringstuff.com/3e/chapter18.html)\n- **Read · optional:** [Harvard CS50P — File I/O](https://cs50.harvard.edu/python/weeks/6/)\n\n## Practice activity\nLoad a small expenses CSV and compute category totals.\n\n## Expected outcome\nCan process structured tabular records.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"97870302-1aef-5f5b-8f89-ccd91b50255c","title":"Complete lesson 23: CSV Records","url":"https://docs.python.org/3/library/csv.html","tag":"hands"}]},{"id":"d6f9220d-0f7f-5d54-92ac-e4630901d91a","dayLabel":"Lesson 24","title":"JSON and Data Validation","hours":"1.25","contentMarkdown":"## Learning objective\nStore nested data and recover from malformed input.\n\n## Understand\nJSON represents arrays, objects, numbers and strings. Use `json.load()` and `json.dump()` for files. Distinguish JSON strings from Python dictionaries, and check expected fields and types before use.\n\n## Read\n- **Read:** [Official Python — json module](https://docs.python.org/3/library/json.html)\n- **Read:** [Automate the Boring Stuff — Chapter 18](https://automatetheboringstuff.com/3e/chapter18.html)\n- **Read · optional:** [Official Python Tutorial](https://docs.python.org/3/tutorial/index.html)\n\n## Practice activity\nSave a list of study tasks as JSON, restart the script, and reload it.\n\n## Expected outcome\nCan serialize and validate nested data.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"467b6aa7-3777-53ea-ad99-26db914732ca","title":"Complete lesson 24: JSON and Data Validation","url":"https://docs.python.org/3/library/json.html","tag":"hands"}]},{"id":"8191177f-09d9-52c7-ab18-b2dbbb283da6","dayLabel":"Lesson 25","title":"Project: Persistent Expense Tracker","hours":"1.75","contentMarkdown":"## Learning objective\nCombine file I/O, data structures and reporting.\n\n## Understand\nCreate an expense tracker that adds transactions, stores them in CSV or JSON, and displays totals by category. Handle missing files by creating an empty collection; keep data stable after restarting.\n\n## Read\n- **Read:** [Harvard CS50P — File I/O](https://cs50.harvard.edu/python/weeks/6/)\n- **Read:** [Automate the Boring Stuff — Chapter 10](https://automatetheboringstuff.com/3e/chapter10.html)\n\n## Practice\n- **Practice · optional:** [Exercism — Python Track](https://exercism.org/tracks/python)\n\n## Practice activity\nRecord 10 sample transactions, restart, and verify totals remain correct.\n\n## Expected outcome\nCompletes a persistent real-world utility.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"dd6942e4-9c13-5085-bf4c-1237cc0e0f02","title":"Complete lesson 25: Project: Persistent Expense Tracker","url":"https://cs50.harvard.edu/python/weeks/6/","tag":"hands"}]}]},{"id":"5a4b49ed-8350-59c3-a042-30591549353d","title":"Week 6 — Object-Oriented Python and Packages","goal":"Model related data and behavior and work in an isolated project environment.","days":[{"id":"094c6e71-4c07-5d0a-a4b8-16c11323d291","dayLabel":"Lesson 26","title":"Classes and Objects","hours":"1.17","contentMarkdown":"## Learning objective\nUnderstand objects and instances.\n\n## Understand\nA class describes a type of object; an instance holds particular values. Use `class`, `__init__`, `self`, and instance attributes. Compare class-based organization with a dictionary-based approach.\n\n## Watch\n- **Watch · optional:** [Corey Schafer — Python Beginner Tutorials (YouTube)](https://www.youtube.com/playlist?list=PL-osiE80TeTskrapNbzXhwoFUiLCjGgY7)\n\n## Read\n- **Read:** [Harvard CS50P — Object-Oriented Programming](https://cs50.harvard.edu/python/weeks/8/)\n- **Read:** [Official Python Tutorial](https://docs.python.org/3/tutorial/index.html)\n\n## Practice activity\nCreate a `Task` class with title, priority and completed state.\n\n## Expected outcome\nCan instantiate a basic class.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"1794d135-f6b7-5f09-a258-d881b779247d","title":"Complete lesson 26: Classes and Objects","url":"https://cs50.harvard.edu/python/weeks/8/","tag":"hands"}]},{"id":"2ad9502f-ed85-55b2-a715-8812f1722d4e","dayLabel":"Lesson 27","title":"Methods and Encapsulation","hours":"1.25","contentMarkdown":"## Learning objective\nPut behavior near the data it changes.\n\n## Understand\nWrite instance methods such as `mark_complete()` and `describe()`. Discuss class versus instance attributes and simple validation. Keep public interfaces clear rather than introducing advanced decorators immediately.\n\n## Watch\n- **Watch:** [Corey Schafer — Python Beginner Tutorials (YouTube)](https://www.youtube.com/playlist?list=PL-osiE80TeTskrapNbzXhwoFUiLCjGgY7)\n\n## Read\n- **Read:** [Harvard CS50P — Object-Oriented Programming](https://cs50.harvard.edu/python/weeks/8/)\n- **Read · optional:** [Official Python Tutorial](https://docs.python.org/3/tutorial/index.html)\n\n## Practice activity\nAdd methods to update task status and format task details.\n\n## Expected outcome\nCan design small classes with methods.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"7131480d-72b4-5152-b0d5-816e731af93a","title":"Complete lesson 27: Methods and Encapsulation","url":"https://cs50.harvard.edu/python/weeks/8/","tag":"hands"}]},{"id":"00d098ab-79e7-588b-bf6a-613d9480b304","dayLabel":"Lesson 28","title":"Composition and Introductory Inheritance","hours":"1.25","contentMarkdown":"## Learning objective\nChoose a simple way to organize collaborating objects.\n\n## Understand\nComposition models objects containing other objects; inheritance models an is-a relationship. Show a TaskManager containing Task objects and briefly compare with subclassing. Prefer composition when it keeps beginner code simpler.\n\n## Watch\n- **Watch · optional:** [Corey Schafer — Python Beginner Tutorials (YouTube)](https://www.youtube.com/playlist?list=PL-osiE80TeTskrapNbzXhwoFUiLCjGgY7)\n\n## Read\n- **Read:** [Harvard CS50P — Object-Oriented Programming](https://cs50.harvard.edu/python/weeks/8/)\n- **Read:** [Official Python Tutorial](https://docs.python.org/3/tutorial/index.html)\n\n## Practice activity\nBuild a `TaskManager` class that stores and filters Task instances.\n\n## Expected outcome\nCan describe composition and inheritance trade-offs.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"8f10e0ef-6e85-5f7b-9aba-cdc900e98830","title":"Complete lesson 28: Composition and Introductory Inheritance","url":"https://cs50.harvard.edu/python/weeks/8/","tag":"hands"}]},{"id":"ce722702-cf1f-5bd2-9fcf-6014678d5e90","dayLabel":"Lesson 29","title":"Virtual Environments and Packages","hours":"1.17","contentMarkdown":"## Learning objective\nKeep project dependencies isolated.\n\n## Understand\nUse `python -m venv .venv` and activate the environment, then use `python -m pip` to install packages. Understand what `requirements.txt` does and why secrets should not be committed. Local installation is optional for browser-only learners.\n\n## Read\n- **Read:** [Official Python — Virtual Environments](https://docs.python.org/3/tutorial/venv.html)\n- **Read:** [Harvard CS50P — Libraries](https://cs50.harvard.edu/python/weeks/4/)\n- **Read · optional:** [Kaggle Learn — Python](https://www.kaggle.com/learn/python)\n\n## Practice activity\nCreate a virtual environment and install a small development dependency.\n\n## Expected outcome\nCan explain and use isolated Python environments.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"310df4db-05d9-5fec-8438-7ea0aa9bf6a3","title":"Complete lesson 29: Virtual Environments and Packages","url":"https://docs.python.org/3/tutorial/venv.html","tag":"hands"}]},{"id":"8701ee3f-a46a-5b3a-94f2-4ee03adc11bd","dayLabel":"Lesson 30","title":"Project: Object-Oriented Task Manager","hours":"1.75","contentMarkdown":"## Learning objective\nBuild a small maintainable multi-file project.\n\n## Understand\nCreate Task and TaskManager classes, add and complete tasks, and save them to JSON. Keep serialization separate from task behavior. Include a clear command-line menu.\n\n## Read\n- **Read:** [Harvard CS50P — Object-Oriented Programming](https://cs50.harvard.edu/python/weeks/8/)\n- **Read:** [Official Python — json module](https://docs.python.org/3/library/json.html)\n\n## Practice\n- **Practice · optional:** [Exercism — Python Track](https://exercism.org/tracks/python)\n\n## Practice activity\nAdd three tasks, complete one, save, restart, and confirm restored state.\n\n## Expected outcome\nBuilds a structured application using classes.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"48f76cc6-6550-550c-a8a0-a6946de97166","title":"Complete lesson 30: Project: Object-Oriented Task Manager","url":"https://cs50.harvard.edu/python/weeks/8/","tag":"hands"}]}]},{"id":"e0271a04-0794-5295-b687-ea3465292254","title":"Week 7 — Testing and Working with APIs","goal":"Check program behavior and consume structured information over HTTP.","days":[{"id":"47b8b446-494c-5f4a-8289-89e4ae1a85ea","dayLabel":"Lesson 31","title":"Assertions and Testable Code","hours":"1.17","contentMarkdown":"## Learning objective\nIdentify expected behavior and edge cases.\n\n## Understand\nTesting compares actual results with expected ones. Explain assertions and why functions that return values are easier to test than code that only prints. Design normal, boundary and invalid-input cases.\n\n## Read\n- **Read:** [Harvard CS50P — Unit Tests](https://cs50.harvard.edu/python/weeks/5/)\n- **Read:** [Official Python — unittest](https://docs.python.org/3/library/unittest.html)\n\n## Practice\n- **Practice · optional:** [Exercism — Python Track](https://exercism.org/tracks/python)\n\n## Practice activity\nWrite expected inputs/outputs for three calculator functions.\n\n## Expected outcome\nCan define meaningful test cases.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"c5adf9a6-35e9-5194-80f6-cf68df7518a2","title":"Complete lesson 31: Assertions and Testable Code","url":"https://cs50.harvard.edu/python/weeks/5/","tag":"hands"}]},{"id":"b310e770-6079-5d22-b86d-654a7e68b305","dayLabel":"Lesson 32","title":"Introduction to pytest","hours":"1.33","contentMarkdown":"## Learning objective\nWrite and run automated tests.\n\n## Understand\nUse test files, `assert`, and `pytest` to verify small functions. Introduce setup of a virtual environment and explain failure output. Keep tests independent and deterministic.\n\n## Read\n- **Read:** [pytest — Getting Started](https://docs.pytest.org/en/stable/getting-started.html)\n- **Read:** [Harvard CS50P — Unit Tests](https://cs50.harvard.edu/python/weeks/5/)\n- **Read · optional:** [Official Python — unittest](https://docs.python.org/3/library/unittest.html)\n\n## Practice activity\nWrite at least five tests for a calculator or task manager function.\n\n## Expected outcome\nCan run a small automated test suite.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"92ec0285-f6ff-5af3-b643-29047817479a","title":"Complete lesson 32: Introduction to pytest","url":"https://docs.pytest.org/en/stable/getting-started.html","tag":"hands"}]},{"id":"59fc6658-1293-56e9-929f-93edac206001","dayLabel":"Lesson 33","title":"HTTP and JSON APIs","hours":"1.25","contentMarkdown":"## Learning objective\nUnderstand requests, responses and data extraction.\n\n## Understand\nAn API provides a programmatic interface. Introduce URLs, GET requests, HTTP status codes and JSON response bodies. Use `requests` as an optional installed package, or inspect sample JSON manually in a browser.\n\n## Read\n- **Read:** [Requests — Quickstart](https://requests.readthedocs.io/en/latest/user/quickstart/)\n- **Read · optional:** [Harvard CS50P — Libraries](https://cs50.harvard.edu/python/weeks/4/)\n\n## Practice\n- **Practice:** [JSONPlaceholder — API Guide](https://jsonplaceholder.typicode.com/guide/)\n\n## Practice activity\nFetch sample public user records and print selected fields.\n\n## Expected outcome\nCan explain how Python consumes an HTTP API.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"adc8d407-9e51-56f0-b458-f4644ab6e928","title":"Complete lesson 33: HTTP and JSON APIs","url":"https://requests.readthedocs.io/en/latest/user/quickstart/","tag":"hands"}]},{"id":"27589c1d-9dd0-529f-8ca8-76993a368eee","dayLabel":"Lesson 34","title":"Network Errors and Data Validation","hours":"1.25","contentMarkdown":"## Learning objective\nHandle unreliable external dependencies.\n\n## Understand\nNetwork requests can time out or return errors; always use a timeout, check response status and validate the expected JSON shape. Do not embed credentials or send private data to public demo APIs. Provide an offline sample-data fallback.\n\n## Read\n- **Read:** [Requests — Quickstart](https://requests.readthedocs.io/en/latest/user/quickstart/)\n- **Read:** [Harvard CS50P — Exceptions](https://cs50.harvard.edu/python/weeks/3/)\n- **Read · optional:** [pytest — Getting Started](https://docs.pytest.org/en/stable/getting-started.html)\n\n## Practice activity\nMake the previous API script handle network failure and missing fields.\n\n## Expected outcome\nCan write defensive API-consuming code.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"503451f0-49a2-5876-a8fa-dced4fc69527","title":"Complete lesson 34: Network Errors and Data Validation","url":"https://requests.readthedocs.io/en/latest/user/quickstart/","tag":"hands"}]},{"id":"d96c8a0c-dc01-5717-9558-6d06f1479ac6","dayLabel":"Lesson 35","title":"Project: Public API Information Explorer","hours":"1.67","contentMarkdown":"## Learning objective\nBuild a tested command-line API client.\n\n## Understand\nUse a public no-key demo API to retrieve a small dataset and display a filtered summary. Keep networking, parsing and formatting in separate functions. Test parsers using offline sample JSON rather than relying on live network calls.\n\n## Read\n- **Read:** [Requests — Quickstart](https://requests.readthedocs.io/en/latest/user/quickstart/)\n- **Read · optional:** [pytest — Getting Started](https://docs.pytest.org/en/stable/getting-started.html)\n\n## Practice\n- **Practice:** [JSONPlaceholder — API Guide](https://jsonplaceholder.typicode.com/guide/)\n\n## Practice activity\nBuild the client, test one successful and two failing scenarios, and document limitations.\n\n## Expected outcome\nCompletes a small API-based application.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"6f4be91a-f250-5baa-b21f-33728fee9474","title":"Complete lesson 35: Project: Public API Information Explorer","url":"https://jsonplaceholder.typicode.com/guide/","tag":"hands"}]}]},{"id":"d376b8cf-3abe-5cc8-9e08-06e6f34df3ae","title":"Week 8 — Automation and Final Capstone","goal":"Apply Python to a complete project with files, validation, tests and documentation.","days":[{"id":"c991dd67-1faa-5e6d-aaa7-d24445349986","dayLabel":"Lesson 36","title":"Automating Repetitive File Tasks","hours":"1.17","contentMarkdown":"## Learning objective\nUse scripts to safely reduce manual work.\n\n## Understand\nAutomation is most useful for repetitive, clearly specified operations. Practice scanning folders, filtering filenames and generating summaries. Use dry-run previews before any rename, move or delete action; never automate access without permission.\n\n## Read\n- **Read:** [Automate the Boring Stuff — Chapter 11](https://automatetheboringstuff.com/3e/chapter11.html)\n- **Read:** [Automate the Boring Stuff — Chapter 12](https://automatetheboringstuff.com/3e/chapter12.html)\n- **Read · optional:** [Official Python — pathlib module](https://docs.python.org/3/library/pathlib.html)\n\n## Practice activity\nWrite a dry-run script that proposes names for files in a sample folder.\n\n## Expected outcome\nCan design a safe basic automation.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"20628753-5252-5808-8354-b387ed6bfd70","title":"Complete lesson 36: Automating Repetitive File Tasks","url":"https://automatetheboringstuff.com/3e/chapter11.html","tag":"hands"}]},{"id":"a1cfc366-6397-5459-b4a3-db3de59ce2a7","dayLabel":"Lesson 37","title":"Project Structure and Readability","hours":"1.17","contentMarkdown":"## Learning objective\nOrganize scripts for maintainability.\n\n## Understand\nSeparate input/output, core logic and data persistence. Add a README explaining setup, commands and expected results. Keep functions short and choose clear filenames; use a virtual environment if third-party dependencies are needed.\n\n## Watch\n- **Watch · optional:** [Corey Schafer — Python Beginner Tutorials (YouTube)](https://www.youtube.com/playlist?list=PL-osiE80TeTskrapNbzXhwoFUiLCjGgY7)\n\n## Read\n- **Read:** [Official Python Tutorial](https://docs.python.org/3/tutorial/index.html)\n- **Read:** [Official Python — Virtual Environments](https://docs.python.org/3/tutorial/venv.html)\n\n## Practice activity\nRefactor one earlier project into separate modules and document its usage.\n\n## Expected outcome\nCan organize and explain a small Python repository.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"fe59618f-7b55-5e6c-aa10-7687a9886670","title":"Complete lesson 37: Project Structure and Readability","url":"https://docs.python.org/3/tutorial/index.html","tag":"hands"}]},{"id":"1d57d611-b945-5b4b-8561-205282508bde","dayLabel":"Lesson 38","title":"Capstone Design","hours":"1.25","contentMarkdown":"## Learning objective\nDefine scope and acceptance criteria before coding.\n\n## Understand\nBuild a Study Planner & Progress Tracker: create study goals, assign weekly tasks, mark tasks complete, persist progress in JSON and show completion percentages. Draw a simple data model and choose a minimal command-line interface.\n\n## Read\n- **Read:** [Automate the Boring Stuff with Python, 3rd Edition](https://automatetheboringstuff.com/3e/)\n- **Read:** [Official Python Tutorial](https://docs.python.org/3/tutorial/index.html)\n\n## Practice\n- **Practice · optional:** [Exercism — Python Track](https://exercism.org/tracks/python)\n\n## Practice activity\nWrite the feature list, sample input data and three acceptance scenarios.\n\n## Expected outcome\nHas a practical, bounded capstone plan.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"e297bcfe-b256-529e-b123-4bde1d81052d","title":"Complete lesson 38: Capstone Design","url":"https://automatetheboringstuff.com/3e/","tag":"hands"}]},{"id":"b627a5fd-1d33-5e62-a64a-5db458177423","dayLabel":"Lesson 39","title":"Build and Test the Capstone","hours":"1.92","contentMarkdown":"## Learning objective\nImplement the end-to-end study tracker.\n\n## Understand\nImplement goal creation, task listing, completion updates, JSON persistence and progress summaries. Reuse concepts from functions, collections, classes, file I/O and tests. Keep the project fully offline so no paid service is required.\n\n## Read\n- **Read:** [pytest — Getting Started](https://docs.pytest.org/en/stable/getting-started.html)\n- **Read:** [Official Python — json module](https://docs.python.org/3/library/json.html)\n- **Read · optional:** [Automate the Boring Stuff — Chapter 10](https://automatetheboringstuff.com/3e/chapter10.html)\n\n## Practice activity\nImplement the core features and test new, partially completed and fully completed goals.\n\n## Expected outcome\nProduces a functioning capstone prototype.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"68afd6b0-96fa-5444-9983-3fbcbbb0781d","title":"Complete lesson 39: Build and Test the Capstone","url":"https://docs.pytest.org/en/stable/getting-started.html","tag":"hands"}]},{"id":"4be2aa84-1d47-51be-a272-890e84aa54cd","dayLabel":"Lesson 40","title":"Documentation and Demonstration","hours":"1.83","contentMarkdown":"## Learning objective\nPresent a usable finished project.\n\n## Understand\nWrite a README, include installation/run instructions, document example usage and list known limitations. Review code readability and tests, then demonstrate the tool with a sample learning plan. Suggest next steps such as a web UI or SQLite without requiring them now.\n\n## Read\n- **Read:** [Automate the Boring Stuff — Chapter 12](https://automatetheboringstuff.com/3e/chapter12.html)\n- **Read:** [pytest — Getting Started](https://docs.pytest.org/en/stable/getting-started.html)\n- **Read · optional:** [Kaggle — Pandas](https://www.kaggle.com/learn/pandas)\n\n## Practice activity\nRecord a short walkthrough or write a sample terminal transcript; verify a fresh user can follow the README.\n\n## Expected outcome\nFinishes a demonstrable portfolio project.\n\n*Mark this lesson complete after doing the activity. This is self-reported progress, not a graded test.*","items":[{"id":"51303c18-798f-5850-b2f8-60fe8aef0b61","title":"Complete lesson 40: Documentation and Demonstration","url":"https://automatetheboringstuff.com/3e/chapter12.html","tag":"hands"}]}]}]'::jsonb;
 v_phase jsonb; v_day jsonb; v_item jsonb;
 v_creator uuid;
 v_revision integer;
 v_limit integer;
