begin
 if current_setting('odu.allow_production_seed',true) is distinct from 'python-foundations-production-approved' then
  raise exception 'Production import requires explicit odu.allow_production_seed confirmation';
 end if;
 if not exists(select 1 from auth.users where id=v_owner and lower(email)='immanjunath@outlook.com' and email_confirmed_at is not null) then raise exception 'Production owner UUID and verified email do not match'; end if;
 if not exists(select 1 from auth.users where id=v_owner) then raise exception 'Selected owner does not exist in Auth'; end if;
 -- A private import does not grant platform publication approval.
 perform pg_advisory_xact_lock(hashtextextended('odu:curated:python-foundations-8-weeks',0));
 -- Match the existing creator RPC's per-user lock and entitlement rule.
 perform pg_advisory_xact_lock(hashtextextended(v_owner::text,0));
 if not exists(select 1 from public.learning_paths where id=v_path) then
  insert into public.user_entitlements(user_id) values(v_owner) on conflict(user_id) do nothing;
  select max_created_paths into v_limit from public.user_entitlements where user_id=v_owner for update;
  if (select count(*) from public.learning_paths where created_by=v_owner)>=v_limit then
   raise exception 'creator quota exceeded' using errcode='check_violation';
  end if;
 end if;
 insert into public.learning_paths(id,title,description,tags,created_by,visibility,wall_status,overview_markdown)
 values(v_path,'Python Foundations — Zero to Real-World Projects','Learn Python through an original eight-week guided journey: start with variables, strings and control flow; master collections and functions; work with files, classes, tests and APIs; and finish with a practical Study Planner & Progress Tracker. Includes curated free resources, hands-on activities and weekly projects.',array['python','beginner','programming','automation','hands-on','eight-weeks','projects']::text[],v_owner,'private','pending_review','**Programming · Beginner · 8 weeks · 40 lessons · 48–64 hours including independent practice**

**Before you start:** No previous programming experience required. A browser is sufficient initially; local Python is recommended from Week 4.

**Who this is for:** Complete beginners, Students, Working professionals, Aspiring automation developers, Aspiring data analysts.

6–8 hours/week; 5 lessons/week. Guided activities total 52 hours 25 minutes.

## What you will learn

- Write and debug small Python programs
- Use control flow, functions and core collections
- Read and write text, CSV and JSON files
- Create basic classes and manage dependencies
- Test code with pytest
- Consume a public JSON API with defensive error handling
- Automate simple repetitive tasks safely
- Build and document a portfolio-ready Python capstone

## Weekly projects

- **Week 1: Python First Steps** — Expense & Tip Calculator. Set up an environment and write small programs using input, output, variables and strings.
- **Week 2: Control Flow and Loops** — Number Guessing Game. Write programs that make decisions and repeat tasks.
- **Week 3: Working with Collections** — Contact Book. Use lists, tuples, sets, dictionaries and string operations to organize data.
- **Week 4: Functions and Reliable Programs** — Modular Calculator. Write reusable functions, use modules and debug failures.
- **Week 5: Files, CSV and JSON** — Persistent Expense Tracker. Save, load and transform real data using the standard library.
- **Week 6: Object-Oriented Python and Packages** — Task Manager with Classes. Model related data and behavior and work in an isolated project environment.
- **Week 7: Testing and Working with APIs** — Public API Information Explorer. Check program behavior and consume structured information over HTTP.
- **Week 8: Automation and Final Capstone** — Study Planner & Progress Tracker. Apply Python to a complete project with files, validation, tests and documentation.

## Resource notes

- External provider courses may be longer than the selected ODU activities; completion of this path does not imply completion of CS50P or Helsinki MOOC.
- Helsinki 2026 edition states it is open until the end of 2026; treat it as a supplemental, time-sensitive resource and revisit in 2027.
- Corey Schafer playlist and Harvard videos are selected as optional explanations; ODU does not rehost them.
- Exercises and explanations are original ODU material; link to providers rather than copying their copyrighted lessons.

ODU completion reflects learner-marked lessons. It is not a graded examination, verified mastery or an external certificate.

